    private int activeTab = 1;
    private int currentPage = 1;
    private int pageSize = 5;

    private string _searchText = "";
    private string SearchText { get => _searchText; set { _searchText = value; currentPage = 1; } }

    private string _searchLop = "";
    private string SearchLop { get => _searchLop; set { _searchLop = value; currentPage = 1; } }

    private List<PhanCongRow> ListGiaoVien = new();
    private List<PhanCongRow> ListGiangDay = new();
    private List<PhanCongRow> ListQuanLy = new();

    private List<PhanCongRow> CurrentTabList => activeTab switch { 1 => ListGiaoVien, 2 => ListGiangDay, _ => ListQuanLy };
    private List<PhanCongRow> FilteredList => CurrentTabList.Where(x =>
        (string.IsNullOrEmpty(SearchText) || x.HoTen.Contains(SearchText, StringComparison.OrdinalIgnoreCase)) &&
        (string.IsNullOrEmpty(SearchLop) || activeTab == 3 || x.Lop.Contains(SearchLop))
    ).ToList();

    private int TotalPages => Math.Max(1, (int)Math.Ceiling((double)FilteredList.Count / pageSize));
    private List<PhanCongRow> PagedList => FilteredList.Skip((currentPage - 1) * pageSize).Take(pageSize).ToList();

    private bool IsAllSelected => PagedList.Any() && PagedList.All(x => x.IsSelected);

    protected override void OnInitialized()
    {
        for (int i = 1; i <= 10; i++) ListGiaoVien.Add(new PhanCongRow { STT = i, MaDinhDanh = $"GV{i:D3}", HoTen = $"Cô GVCN {i}", Lop = i % 2 == 0 ? "1A1" : "1A2", HocKy = "Cả năm" });
        for (int i = 1; i <= 8; i++) ListGiangDay.Add(new PhanCongRow { STT = i, MaDinhDanh = $"BM{i:D3}", HoTen = $"Thầy Bộ Môn {i}", Lop = "1A1 (Thể chất)", HocKy = "HK1" });
        ListQuanLy.Add(new PhanCongRow { STT = 1, MaDinhDanh = "HT001", HoTen = "Hiệu Trưởng A", ChucVu = "Hiệu trưởng" });
    }

    private void ToggleSelectAll(ChangeEventArgs e)
    {
        bool isChecked = (bool)(e.Value ?? false);
        foreach (var item in PagedList) item.IsSelected = isChecked;
    }

    private void ChangePage(int newPage) { if (newPage >= 1 && newPage <= TotalPages) currentPage = newPage; }
    private void SwitchTab(int tabIndex) { activeTab = tabIndex; SearchText = ""; SearchLop = ""; currentPage = 1; }
    private string GetTabTitle() => activeTab switch { 1 => "Phân công GVCN", 2 => "Phân công giảng dạy", _ => "Phân công quản lý" };

